metadata.ans:document:
{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "en"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "kruskal(n, edges)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d2"
          },
          "args": "n",
          "result": ""
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "mst = []"
        },
        {
          "id": "b3",
          "kind": "for",
          "text": "for w, u, v in sorted(edges)    # lightest edge first",
          "body": [
            {
              "id": "b4",
              "kind": "call",
              "target": {
                "kind": "local",
                "diagram": "d4"
              },
              "args": "u, v",
              "result": "merged"
            },
            {
              "id": "b5",
              "kind": "if",
              "text": "merged",
              "yes": {
                "id": "r1",
                "body": [
                  {
                    "id": "b6",
                    "kind": "process",
                    "text": "mst.append((u, v, w))"
                  }
                ]
              },
              "no": {
                "id": "r2",
                "body": [
                  {
                    "id": "b7",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            }
          ]
        },
        {
          "id": "b8",
          "kind": "process",
          "text": "return mst"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "make_sets(n)"
      },
      "body": [
        {
          "id": "b9",
          "kind": "process",
          "text": "parent = list(range(n))"
        },
        {
          "id": "b10",
          "kind": "process",
          "text": "rank = [0] * n"
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "method",
        "text": "find(x)"
      },
      "body": [
        {
          "id": "b11",
          "kind": "if",
          "text": "parent[x] != x",
          "yes": {
            "id": "r3",
            "body": [
              {
                "id": "b12",
                "kind": "call",
                "target": {
                  "kind": "local",
                  "diagram": "d3"
                },
                "args": "parent[x]",
                "result": "root"
              },
              {
                "id": "b13",
                "kind": "process",
                "text": "parent[x] = root    # path compression"
              }
            ]
          },
          "no": {
            "id": "r4",
            "body": [
              {
                "id": "b14",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b15",
          "kind": "process",
          "text": "return parent[x]"
        }
      ]
    },
    {
      "id": "d4",
      "head": {
        "kind": "method",
        "text": "union(x, y)"
      },
      "body": [
        {
          "id": "b16",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d3"
          },
          "args": "x",
          "result": "rx"
        },
        {
          "id": "b17",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d3"
          },
          "args": "y",
          "result": "ry"
        },
        {
          "id": "b18",
          "kind": "if",
          "text": "rx == ry",
          "yes": {
            "id": "r5",
            "body": [
              {
                "id": "b19",
                "kind": "exit",
                "text": "return False    # already in one set"
              }
            ]
          },
          "no": {
            "id": "r6",
            "body": [
              {
                "id": "b20",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b21",
          "kind": "if",
          "text": "rank[rx] < rank[ry]",
          "yes": {
            "id": "r7",
            "body": [
              {
                "id": "b22",
                "kind": "process",
                "text": "rx, ry = ry, rx"
              }
            ]
          },
          "no": {
            "id": "r8",
            "body": [
              {
                "id": "b23",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b24",
          "kind": "process",
          "text": "parent[ry] = rx    # lower tree under the higher"
        },
        {
          "id": "b25",
          "kind": "if",
          "text": "rank[rx] == rank[ry]",
          "yes": {
            "id": "r9",
            "body": [
              {
                "id": "b26",
                "kind": "process",
                "text": "rank[rx] += 1"
              }
            ]
          },
          "no": {
            "id": "r10",
            "body": [
              {
                "id": "b27",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b28",
          "kind": "process",
          "text": "return True"
        }
      ]
    }
  ],
  "view": {
    "folded": [],
    "opened": [],
    "bands": true,
    "resultSymbol": "←"
  }
}
